import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.BU4O3IzQ.js";const d=JSON.parse('{"title":"AI 动态 · 2026-08-04","description":"","frontmatter":{"title":"AI 动态 · 2026-08-04","date":"2026-08-04T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-04.md","filePath":"news/2026-08/ai-news-2026-08-04.md","lastUpdated":1786092171000}'),n={name:"news/2026-08/ai-news-2026-08-04.md"};function o(i,e,c,p,l,h){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-08-04" tabindex="-1">AI 动态 · 2026-08-04 <a class="header-anchor" href="#ai-动态-·-2026-08-04" aria-label="Permalink to &quot;AI 动态 · 2026-08-04&quot;">​</a></h1><blockquote><p>截至 2026-08-04。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="deepseek-v4-flash低价风暴席卷硅谷-海外平台争相补贴" tabindex="-1">DeepSeek V4 Flash低价风暴席卷硅谷，海外平台争相补贴 <a class="header-anchor" href="#deepseek-v4-flash低价风暴席卷硅谷-海外平台争相补贴" aria-label="Permalink to &quot;DeepSeek V4 Flash低价风暴席卷硅谷，海外平台争相补贴&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-04">2026-08-04</time></p><p>DeepSeek V4 Flash 以极低定价引发全球开发者狂欢，OpenCode 单日跑 8T tokens，Nous Portal 限时一折，Cline 因成本过低直接翻三倍免费额度。V4-Flash-0731 通过重跑后训练，DeepSWE 得分从 7.3 飙至 54.4，能力直逼 Opus 4.8，缓存未命中时每百万输入 token 仅 $0.14。对读者：低成本高性能模型正成为开发者主力选择，可优先评估迁移至 V4 Flash 以大幅降低推理成本。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/465814.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="亿级日活出海app的算力生死劫-跨云架构砍掉75-gpu集群" tabindex="-1">亿级日活出海App的算力生死劫：跨云架构砍掉75% GPU集群 <a class="header-anchor" href="#亿级日活出海app的算力生死劫-跨云架构砍掉75-gpu集群" aria-label="Permalink to &quot;亿级日活出海App的算力生死劫：跨云架构砍掉75% GPU集群&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-04">2026-08-04</time></p><p>一家DAU破亿的AI穿搭出海应用因推理成本倒挂陷入亏损：每用户ARPU仅2美元，云端算力与传输成本却达3美元。团队通过跨云架构优化，将GPU集群成本砍掉75%，破解了算力租金、天价流量税与网络延迟三重锁链。对读者：高并发AI应用应重新审视云资源调度与流量成本，跨云架构是降低推理成本的有效路径。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/465732.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="前海母基金数亿元押注om-ai联汇-端侧物理ai加速商业化" tabindex="-1">前海母基金数亿元押注Om AI联汇，端侧物理AI加速商业化 <a class="header-anchor" href="#前海母基金数亿元押注om-ai联汇-端侧物理ai加速商业化" aria-label="Permalink to &quot;前海母基金数亿元押注Om AI联汇，端侧物理AI加速商业化&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-04">2026-08-04</time></p><p>杭州联汇科技（Om AI联汇）完成数亿元新一轮融资，由前海母基金领投，杭州政府产业基金参投。公司同步开源VLX-Seek 1.5端侧原生多模态模型，3B参数版本多项指标超越英伟达LocateAnything-3B，无人机具身场景准确率提升62.9%。商业化已落地AIPC、具身智能与视障辅助等领域。对读者：端侧物理AI正成为资本与产业焦点，关注VLX系列开源模型可提前布局端侧智能应用。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/465785.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="腾讯混元发布hy-asr-3-0-preview-语音识别开始理解上下文" tabindex="-1">腾讯混元发布Hy ASR 3.0 preview：语音识别开始理解上下文 <a class="header-anchor" href="#腾讯混元发布hy-asr-3-0-preview-语音识别开始理解上下文" aria-label="Permalink to &quot;腾讯混元发布Hy ASR 3.0 preview：语音识别开始理解上下文&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-04">2026-08-04</time></p><p>腾讯混元正式发布新一代语音识别模型Hy ASR 3.0 preview，基于Hy3大模型底座，融合高精度识别与深度语义理解。在开源评测集中，中文普通话WER 3.34%、英语2.62%、粤语3.12%，整体领先竞品。新模型支持上下文感知、热词注入增强，并针对高噪、耳语等复杂声学场景专项优化，已接入腾讯元宝。对读者：具备上下文理解能力的ASR将显著提升语音交互体验，可关注其API接入与专业场景适配。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/465973.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="kimi-k3与deepseek-v4之间-隔着原生多模态的时间差" tabindex="-1">Kimi K3与DeepSeek V4之间，隔着原生多模态的时间差 <a class="header-anchor" href="#kimi-k3与deepseek-v4之间-隔着原生多模态的时间差" aria-label="Permalink to &quot;Kimi K3与DeepSeek V4之间，隔着原生多模态的时间差&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">36氪</span><time datetime="2026-08-04">2026-08-04</time></p><p><img src="https://img.36krcdn.com/hsossms/20260804/v2_1c0344c251734fb08e4c00b9182c7ac8@6252890@ai_oswg920317oswg1053oswg495_img_png~tplv-1marlgjv7f-ai-v3:600:400:600:400:q70.jpg" alt="配图"></p><p>月之暗面发布的Kimi K3（2.8万亿参数MoE）以原生多模态能力登顶Arena Frontend Code榜单，通过&quot;vision in the loop&quot;机制让模型在代码与截图间反复迭代，能精准发现网页视觉偏差。相比之下，DeepSeek V4在原生多模态上存在时间差。阿里Qwen3.8-Max与字节Doubao-Seed-2.1也均将视觉作为基础能力。对读者：原生多模态正成为Agent长链任务的关键反馈机制，选型时需重点评估模型的视觉闭环能力。</p><p class="news-entry-source"><a href="https://36kr.com/p/3924826666301831?f=rss" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="开源版claude-science来了-北大联合实验室发布openai4s-mit协议零依赖" tabindex="-1">开源版Claude Science来了：北大联合实验室发布OpenAI4S，MIT协议零依赖 <a class="header-anchor" href="#开源版claude-science来了-北大联合实验室发布openai4s-mit协议零依赖" aria-label="Permalink to &quot;开源版Claude Science来了：北大联合实验室发布OpenAI4S，MIT协议零依赖&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-04">2026-08-04</time></p><p>北京大学与元空AI Agent联合实验室正式开源科研智能体项目OpenAI4S，采用MIT协议、核心零依赖，沿Code-as-Action思路独立复现Claude Science的引擎、持久内核与host-RPC协议。项目内置30余项科研Skills，支持数据检索、代码执行、图表生成与报告产出，并提供版本化科研产物管理。对读者：科研自动化Agent有了开源替代方案，可基于OpenAI4S快速搭建定制化科研工作流。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/466386.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="uber开源adr-面向企业ai-agent的安全观测与威胁检测框架" tabindex="-1">Uber开源ADR：面向企业AI Agent的安全观测与威胁检测框架 <a class="header-anchor" href="#uber开源adr-面向企业ai-agent的安全观测与威胁检测框架" aria-label="Permalink to &quot;Uber开源ADR：面向企业AI Agent的安全观测与威胁检测框架&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">uber/ADR</span><time datetime="2026-08-04">2026-08-04</time></p><p><img src="https://opengraph.githubassets.com/1/uber/ADR" alt="配图"></p><p>Uber正式开源ADR（Agent Defense &amp; Response），该框架已在Uber内部部署，用于保障企业AI Agent安全。ADR提供可观测性、安全基准测试与威胁检测能力，帮助团队监控Agent行为、识别异常并建立安全防线。对读者：企业级Agent落地需配套安全治理，ADR可作为观测与防护的参考实现。</p><p class="news-entry-source"><a href="https://github.com/uber/ADR" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="browser-use-video-use-用编码agent编辑视频的开源项目" tabindex="-1">browser-use/video-use：用编码Agent编辑视频的开源项目 <a class="header-anchor" href="#browser-use-video-use-用编码agent编辑视频的开源项目" aria-label="Permalink to &quot;browser-use/video-use：用编码Agent编辑视频的开源项目&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">browser-use/video-use</span><time datetime="2026-08-04">2026-08-04</time></p><p><img src="https://opengraph.githubassets.com/1/browser-use/video-use" alt="配图"></p><p>browser-use团队推出video-use开源项目，让编码Agent能够直接编辑视频。该项目将Agent能力从浏览器操作扩展到视频处理领域，支持通过自然语言指令驱动视频剪辑、特效添加等任务。对读者：Agent能力边界正快速拓展，视频编辑自动化有望成为内容创作新范式。</p><p class="news-entry-source"><a href="https://github.com/browser-use/video-use" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github-copilot-cli重新设计-新增选项卡与免配置文件工具设置" tabindex="-1">GitHub Copilot CLI重新设计：新增选项卡与免配置文件工具设置 <a class="header-anchor" href="#github-copilot-cli重新设计-新增选项卡与免配置文件工具设置" aria-label="Permalink to &quot;GitHub Copilot CLI重新设计：新增选项卡与免配置文件工具设置&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-04">2026-08-04</time></p><p><img src="https://static001.infoq.cn/resource/image/85/3a/85564d253abfc76e927ce7bccf7be83a.jpg" alt="配图"></p><p>GitHub正式推出重新设计的Copilot CLI终端界面，新增会话、Gists、Issues与Pull requests选项卡布局，支持鼠标选择与拖动重排。工具配置改为引导式会话体验，可通过/mcp add交互表单或/mcp search浏览MCP Registry直接安装服务器，无需手动编辑配置文件。新界面还优化了主题适配与屏幕阅读器支持。对读者：Copilot CLI的交互升级大幅降低MCP与插件配置门槛，值得立即体验。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/wybFeXucFGaobN7wQjev?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="agent记忆不能只靠聊天记录-tencentdb-agent-memory的四层资产体系" tabindex="-1">Agent记忆不能只靠聊天记录：TencentDB Agent Memory的四层资产体系 <a class="header-anchor" href="#agent记忆不能只靠聊天记录-tencentdb-agent-memory的四层资产体系" aria-label="Permalink to &quot;Agent记忆不能只靠聊天记录：TencentDB Agent Memory的四层资产体系&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-04">2026-08-04</time></p><p><img src="https://static001.infoq.cn/resource/image/db/7e/dbyycedf391b2db23805ea437f069a7e.jpg" alt="配图"></p><p>腾讯云数据库提出Agent Memory方案，将团队记忆抽象为四类原子资产：Chat Memory记录任务背景与决策、LLM-Wiki承载项目文档、Code Graph描述代码调用关系、Skill封装团队SOP。该体系让有效状态可跨session、跨Agent、跨框架继承，解决Agent每次对话重新开始的问题。对读者：构建Agent应用时，应系统设计记忆分层与资产治理，而非简单堆叠聊天记录。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/qm3RHL133SESFZJGrmeA?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="给agent装上方向盘和刹车-harness时代的工程新范式" tabindex="-1">给Agent装上方向盘和刹车：Harness时代的工程新范式 <a class="header-anchor" href="#给agent装上方向盘和刹车-harness时代的工程新范式" aria-label="Permalink to &quot;给Agent装上方向盘和刹车：Harness时代的工程新范式&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-04">2026-08-04</time></p><p><img src="https://static001.infoq.cn/resource/image/11/86/110b47c994b1aae432eba5da7c34b486.jpg" alt="配图"></p><p>InfoQ《极客有约》邀请阿里云、NoDesk AI、腾讯专家探讨Agent Infra从可用到高效规模化的路径。核心观点：Harness的本质是用工程系统承接和约束不确定性，让Agent做正确的事并正确地做事；可观测性是诊断错误、形成优化飞轮的基础；企业需通过本体论将人用上下文翻译为Agent可理解语言。对读者：Agent规模化落地需配套Harness工程体系，可观测性与语义对齐是优先建设项。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/QxdM6J3uFpZA0CXgNhDq?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="amazon-eks新增升级后7天内回滚kubernetes版本功能" tabindex="-1">Amazon EKS新增升级后7天内回滚Kubernetes版本功能 <a class="header-anchor" href="#amazon-eks新增升级后7天内回滚kubernetes版本功能" aria-label="Permalink to &quot;Amazon EKS新增升级后7天内回滚Kubernetes版本功能&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-04">2026-08-04</time></p><p><img src="https://static001.infoq.cn/resource/image/cf/cc/cf05d656bd02c552dba1c6f2eb4ec5cc.jpg" alt="配图"></p><p>Amazon EKS推出Kubernetes版本回滚支持，升级后7天内出现问题可将控制平面回滚至之前版本，同时保留etcd数据、工作负载和持久卷。回滚每次仅涉及一个次要版本，EKS会运行集群分析检查准备情况并提示节点版本不匹配等问题。该功能解决了Kubernetes控制平面升级长期以来的&quot;单行道&quot;困境。对读者：EKS用户可放心推进版本升级，回滚机制显著降低了升级风险。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/5si5hgXIKQjbwFwyJ5aC?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="harmonyos-7抹平系统能力接入鸿沟-skill与agent可被封装调用" tabindex="-1">HarmonyOS 7抹平系统能力接入鸿沟：Skill与Agent可被封装调用 <a class="header-anchor" href="#harmonyos-7抹平系统能力接入鸿沟-skill与agent可被封装调用" aria-label="Permalink to &quot;HarmonyOS 7抹平系统能力接入鸿沟：Skill与Agent可被封装调用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-08-04">2026-08-04</time></p><p>华为HDD·HarmonyOS创新论坛西安站展示HarmonyOS 7在终端开发上的突破：通过星河互联一碰快传实现跨设备精准传输，系统能力Skill化让AI服务可被封装调用，数字内容走出平面。新系统大幅缩短了系统技术抵达真实应用的工程距离，降低多设备互联与AI集成的开发成本。对读者：鸿蒙开发者应关注Skill化封装能力，可显著减少系统能力接入的重复造轮子成本。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/08/466262.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const u=a(n,[["render",o]]);export{d as __pageData,u as default};
